import { createGame, board, currentPlayer, legalMoves, applyMove, status } from '/Users/leonchan/WorkSpace/IDX-Tic-Tac-Toe/src/engine.js';

let terminals=0, draws=0, maxLen=0, lineAt9=0, lineWins=0, fillWins=0, bad=[];
function walk(state){
  const s=status(state); const moves=legalMoves(state);
  if(s.over){
    terminals++;
    if(s.winner===null){draws++;bad.push('draw reachable');}
    if(moves.length!==0) bad.push('terminal with legal moves');
    maxLen=Math.max(maxLen,s.moveCount);
    if(s.reason==='line') lineWins++; else fillWins++;
    if(s.moveCount===9 && s.reason==='line') lineAt9++;
    return;
  }
  if(moves.length===0) bad.push('non-terminal with no moves');
  for(const m of moves) walk(applyMove(state,m));
}
